_DURATION_RE = re.compile(r'(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?')

_MULTIPLIERS = (86400, 3600, 60, 1)


def parse_duration(s):
    """Convert a duration string such as '1h30m' to an integer of seconds.

    Raises ValueError for anything that is not a sequence of non-negative
    integer amounts followed by d, h, m or s units in that order, with each
    unit appearing at most once.
    """
    if not isinstance(s, str):
        raise ValueError('duration must be a string')

    text = s.strip()
    match = _DURATION_RE.fullmatch(text)
    if match is None or not any(value is not None for value in match.groups()):
        raise ValueError(f'invalid duration: {s!r}')

    return sum(
        int(value) * multiplier
        for value, multiplier in zip(match.groups(), _MULTIPLIERS)
        if value is not None
    )
